select * from pcd_uploads_session_table
where uploads_user_id=#{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  and (uploads_space_id=#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
    or (#{personalSpace}=true and uploads_space_id is null)
    or #{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler} is null)
  and uploads_status = 'uploading';

select * from pcd_uploads_session_table
where uploads_status = 'uploading'
  and uploads_starting_time < #{expireTime};
